<?php
namespace ADMIN\AdminBundle\Entity;use Doctrine\ORM\EntityRepository;class PersonaObservadaRepository extends EntityRepository
{    public function getByFilter($filter){        $sSql = "SELECT i FROM ADMINAdminBundle:PersonaObservada i WHERE 1=1 ";                if(!empty($filter['txtApellido'])){            if($filter['txtApellido'] != ""){                $sSql .= " and upper(i.apellido) like upper( '%".$filter['txtApellido']   ."%' )";            }        }                if(!empty($filter['txtNombre'])){            if($filter['txtNombre'] != ""){                $sSql .= " and upper(i.nombre) like upper( '%".$filter['txtNombre']   ."%' )";            }        }                if($filter['lstEstado'] != ""){            $now = new \Datetime();            if($filter['lstEstado'] == "A"){                $sSql .= " and i.borrado = 0 and i.fecDesde <= to_date('".$now->format('d/m/Y')."','dd/mm/yyyy') and i.fecHasta >= to_date('".$now->format('d/m/Y')."','dd/mm/yyyy')";            }else if($filter['lstEstado'] == "B"){                $sSql .= " and i.borrado = 1";            }else if($filter['lstEstado'] == "N"){                $sSql .= " and i.borrado = 0 and i.fecDesde > to_date('".$now->format('d/m/Y')."','dd/mm/yyyy') or i.fecHasta < to_date('".$now->format('d/m/Y')."','dd/mm/yyyy')";            }        }                        if(!empty($filter['fDependencia'])){            $sSql .= " and i.dependencia = ".$filter['fDependencia'];        }                $sSql .= " ORDER BY i.id DESC";                        $query = $this->getEntityManager()->createQuery( $sSql  );                return $query;    }        public function getConsultas($id,$filter){                $sSql = "SELECT c FROM ADMINAdminBundle:ConsultaPersonaObservada c LEFT JOIN c.iaId i WHERE c.personaObservada = ".$id;                if(!empty($filter['txtUsuario'])){            if($filter['txtUsuario'] != ""){                $sSql .= " and upper( i.iaUsuario    ) like upper( '%".$filter['txtUsuario']   ."%' )";            }        }                if(!empty($filter['txtDependencia'])){            if($filter['txtDependencia'] != ""){                $sSql .= " and upper(i.iaUsuarioDependencia) like upper( '%".$filter['txtDependencia']   ."%' )";            }        }                if(!empty($filter["fDesde"])){            $sSql .= " and i.iaTimestamp >= to_date( '".$filter["fDesde"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                if(!empty($filter["fHasta"])){            $sSql .= " and i.iaTimestamp <= to_date( '".$filter["fHasta"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                if(!empty($filter["lstResultado"])){            if($filter["lstResultado"] == "OTROS"){                $sSql .= " and i.iaResultCode NOT IN ('NO_ANSWER','NO_ERROR')";            }else{                $sSql .= " and i.iaResultCode = '".$filter["lstResultado"]."'";            }        }                if(!empty($filter["lstEstado"])){            $sSql .= " and c.estado = '".$filter["lstEstado"]."'";            }                $sSql .= " ORDER BY c.id DESC";                $query = $this->getEntityManager()->createQuery( $sSql  );                        return $query;    }        public function getAuditoria($id,$filter){                $sSql = "SELECT a FROM ADMINAdminBundle:AuditoriaPerObs a LEFT JOIN a.usuAlta u WHERE a.personaObservada = ".$id;                if(!empty($filter['txtUsuario'])){            if($filter['txtUsuario'] != ""){                $sSql .= " and upper( u.usuario ) like upper( '%".$filter['txtUsuario']."%' )";            }        }                if(!empty($filter["fDesde"])){            $sSql .= " and a.fecAlta >= to_date( '".$filter["fDesde"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                if(!empty($filter["fHasta"])){            $sSql .= " and a.fecAlta <= to_date( '".$filter["fHasta"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                $sSql .= " ORDER BY a.id DESC";                $query = $this->getEntityManager()->createQuery( $sSql  );                return $query;    }            public function getVencimientos($dependencia){        $currentDate = new \Datetime();                $sSql = "SELECT p FROM ADMINAdminBundle:PersonaObservada p WHERE p.borrado = 0";                $sSql .= " and p.dependencia = ".$dependencia->getId();                $sSql .= " and p.fecHasta >= to_date( '".$currentDate->format('d/m/Y')." 00:00:00', 'DD/MM/YYYY HH24:MI:SS' )";                $currentDate->modify("+5 day");                $sSql .= " and p.fecHasta <= to_date( '".$currentDate->format('d/m/Y')." 23:59:59', 'DD/MM/YYYY HH24:MI:SS' )";                $sSql .= " ORDER BY p.fecHasta, p.id ASC";                $query = $this->getEntityManager()->createQuery( $sSql  );                return $query;    }
}
  